import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.Ch_0qWu9.js";const f=JSON.parse('{"title":"Third-party notices","description":"","frontmatter":{"sourcePath":"docs/licenses/THIRD_PARTY_NOTICES.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/THIRD_PARTY_NOTICES.md","alternateUrl":"/TCSExam/docs/zh/licenses/THIRD_PARTY_NOTICES/","alternateAnchors":{"third-party-notices":"third-party-notices","solver-code-data-and-reference-materials":"solver-code-data-and-reference-materials","lean-construction-and-system-components":"lean-construction-and-system-components","additional-full-materials":"additional-full-materials"}},"headers":[],"relativePath":"licenses/THIRD_PARTY_NOTICES/index.md","filePath":"licenses/THIRD_PARTY_NOTICES/index.md"}'),n={name:"licenses/THIRD_PARTY_NOTICES/index.md"};function i(d,e,s,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="third-party-notices" tabindex="-1">Third-party notices <a class="header-anchor" href="#third-party-notices" aria-label="Permalink to &quot;Third-party notices&quot;">​</a></h1><p>This page lists component sources, licenses and attribution requirements. It is for users reusing task materials or preparing a distribution.</p><p>Third-party terms apply to the corresponding files in task folders and containers. Original license texts are under <code>docs/licenses/third-party/</code>. Use <a href="/TCSExam/docs/licenses/distribution/">distribution conditions</a> for resource-specific sharing scope and <a href="/TCSExam/docs/licenses/full-review/">component records</a> for pinned source and file lists.</p><h2 id="solver-code-data-and-reference-materials" tabindex="-1">Solver code, data, and reference materials <a class="header-anchor" href="#solver-code-data-and-reference-materials" aria-label="Permalink to &quot;Solver code, data, and reference materials&quot;">​</a></h2><p>Read each row for the named component and its required attribution. Paths under <code>environment/app/</code> are relative to the task identified in that row.</p><table tabindex="0"><thead><tr><th>Resource and location</th><th>Source, author, and terms</th><th>Attribution and distribution conditions</th></tr></thead><tbody><tr><td>BPPLIB instances: <code>tasks/solver/online/bpp-bpplib/environment/app/instances/</code>, <code>library/</code>, and <code>tests/official-instances/</code></td><td>M. Delorme, M. Iori, S. Martello, and the authors of each family; <a href="https://github.com/mdelorme2/BPPLIB/blob/main/LICENSE" target="_blank" rel="noreferrer">BPPLIB license</a>, CC BY-NC-ND 4.0</td><td>Retain original attribution and license. The non-commercial and no-derivatives conditions remain in force.</td></tr><tr><td>BPPLIB packings, registry-table extraction, and transformed data, including hidden judging data</td><td>Derived from the BPPLIB data and solution logs under the same CC BY-NC-ND 4.0 terms</td><td>Obtain the originals and prepare any required files locally. Keep derived files local under the <a href="/TCSExam/docs/licenses/distribution/">distribution conditions</a>. The <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/bpplib-reconstruction.json" target="_blank" rel="noreferrer">source and preparation record</a> and <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/bpplib-table-source.json" target="_blank" rel="noreferrer">table-source record</a> identify the materials.</td></tr><tr><td>Course-timetabling instances and transformations: <code>tasks/solver/online/curriculum-itc2007/</code></td><td>Sara Ceschia, Francesca Da Ros, Luca Di Gaspero, Andrea Schaerf; <a href="https://github.com/iolab-uniud/cb-ctt/blob/main/LICENSE.txt" target="_blank" rel="noreferrer">cb-ctt license</a>, CC BY 4.0</td><td>Attribute the authors and retain conversion notes. <code>comp15</code> corresponds to official <code>comp03</code>; the license basis does not extend to <code>comp11</code>. See the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/ctt-source-comparison.json" target="_blank" rel="noreferrer">source comparison</a>.</td></tr><tr><td>CPSolver wrapper source: <code>environment/app/cpsolver-src/</code></td><td>Tomáš Müller et al.; <a href="https://github.com/tomas-muller/cpsolver-itc2007" target="_blank" rel="noreferrer">original repository</a>; source headers specify LGPL-3.0-or-later</td><td>Retain source headers, original notices, and modification notes. Provide the corresponding source and build materials with a distributed binary.</td></tr><tr><td>CPSolver core JAR: <code>environment/app/lib/cpsolver-all-1.2.jar</code></td><td>CPSolver 1.2_bld46; <a href="https://github.com/tomas-muller/cpsolver-itc2007/blob/a253a5a45a5b148d5a8981c3fd0af5ecf9ae4b06/lib/cpsolver-all-1.2.jar" target="_blank" rel="noreferrer">upstream task-package source</a>; LGPL-3.0 text in the JAR</td><td>The <a href="/TCSExam/docs/licenses/cpsolver-source/">source, build, and replacement guide</a> identifies the corresponding release source and required package contents. Retain the LGPL and related dependency notices.</td></tr><tr><td>dom4j 1.6.1: <code>environment/app/lib/dom4j-1.6.1.jar</code></td><td>MetaStuff Ltd.; five-clause BSD-style terms in the JAR&#39;s <code>META-INF/LICENSE.txt</code></td><td>Preserve the full notice, including attribution, no-endorsement, and name restrictions. Keep all five clauses intact.</td></tr><tr><td>log4j 1.2.8: <code>environment/app/lib/log4j-1.2.8.jar</code></td><td>Apache Software Foundation; Apache Software License 1.1 in the <a href="https://archive.apache.org/dist/logging/log4j/1.2.8/jakarta-log4j-1.2.8.tar.gz" target="_blank" rel="noreferrer">official source archive</a></td><td>Retain the complete license, its required acknowledgment, and its name restrictions. See <code>third-party/Log4j-1.2.8-Apache-1.1.txt</code>.</td></tr><tr><td>Official ITC 2007 <code>validator.cc</code> and OptHub best-known solutions</td><td>Andrea Schaerf, Luca Di Gaspero, and solution contributors; <a href="https://www.eeecs.qub.ac.uk/itc2007/" target="_blank" rel="noreferrer">ITC 2007</a> and <a href="https://opthub.uniud.it/" target="_blank" rel="noreferrer">OptHub</a></td><td>Redistribution terms for these files remain unconfirmed. Obtain them from their original sources and follow their individual terms.</td></tr><tr><td>MQLib software: <code>tasks/solver/online/maxcut-mqlib/environment/app/mqlib/</code></td><td>Iain Dunning, Swati Gupta, and John Silberholz; <a href="https://github.com/MQLib/MQLib/blob/master/LICENSE" target="_blank" rel="noreferrer">MQLib license</a>, MIT</td><td>Retain copyright, the MIT license, and notices for modified code. Instance data has the family-specific terms below; consult each source for accompanying papers and supplements.</td></tr><tr><td>MQLib instances and transformed copies</td><td>The <a href="https://github.com/MQLib/MQLib/blob/master/scripts/downloadAllGraphs.py" target="_blank" rel="noreferrer">MQLib download script</a> points to sources hosted separately</td><td>Instance terms vary by family. Obtain each item from its source and follow the conditions for that family.</td></tr><tr><td>OR-Library instances <code>g001642</code>, <code>g002564</code>, and <code>g002776</code>, used by MQLib</td><td>J. E. Beasley; <a href="https://people.brunel.ac.uk/~mastjjb/jeb/orlib/legal.html" target="_blank" rel="noreferrer">OR-Library legal page</a>, MIT</td><td>Retain Beasley&#39;s copyright, the full MIT text, and attribution for the MQLib transformation. This basis covers only these three instances. See the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/mqlib-family-license-review.json" target="_blank" rel="noreferrer">MQLib family record</a>.</td></tr><tr><td>ROADEF/EURO 2012 instances, rearranged copies, and Google checker</td><td>Pinned <a href="https://github.com/google/or-tools/tree/06376d5ff5bbaead64e9b2df61ccbe74e99e5f8c/data/roadef_challenge_2011/solution_checker" target="_blank" rel="noreferrer">Google OR-Tools source</a>, Apache-2.0</td><td>Retain Google attribution, the license, and notes on changes to the source files and data. The <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/roadef-hidden-source-chain.json" target="_blank" rel="noreferrer">source-chain record</a> identifies the corresponding materials.</td></tr><tr><td>ROADEF challenge PDF and project-generated reference assignments</td><td><a href="https://www.roadef.org/challenge/2012/en/sujet.php" target="_blank" rel="noreferrer">Official challenge page</a>; the reference assignments were generated by this project</td><td>Redistribution terms for the PDF are not established; obtain it from the official source. The reference assignments are project-generated numerical outputs, documented in the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/roadef-hidden-source-chain.json" target="_blank" rel="noreferrer">source record</a>. The source record identifies them separately from the PDF and checker code.</td></tr><tr><td>ROADEF checker source: <code>environment/app/checker-src/</code></td><td>Copyright 2011 Google Inc. All Rights Reserved.; pinned official source above, Apache-2.0</td><td>Retain Google&#39;s copyright and license, and identify the blank-line changes. See the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/roadef-checker-source.json" target="_blank" rel="noreferrer">source comparison</a>.</td></tr><tr><td>Qute source: <code>tasks/solver/online/qbf-qbfeval/environment/app/qute/</code></td><td>Friedrich Slivovsky and Tomáš Peitl; <a href="https://github.com/fslivovsky/qute/tree/67c5e54e96eb2ba7aedc18186d5ae62230c4caf8" target="_blank" rel="noreferrer">pinned source</a>; MIT terms in the <a href="https://doi.org/10.5281/zenodo.14536421" target="_blank" rel="noreferrer">authors&#39; software supplement</a></td><td>Retain the source revision, copyright, full license, and the fact that the license was added after the older source snapshot. Applicability of the later MIT notice to the older snapshot remains unconfirmed. See the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qute-version-comparison.json" target="_blank" rel="noreferrer">version comparison</a>.</td></tr><tr><td>MiniSat and docopt.cpp bundled with Qute</td><td>Original component authors; bundled MiniSat, <code>LICENSE-MIT</code>, and <code>LICENSE-Boost-1.0</code> files</td><td>Retain each component&#39;s original notice separately, including both docopt.cpp license texts.</td></tr><tr><td>qrp2rup</td><td>Tomáš Peitl; 2026 <a href="https://doi.org/10.5281/zenodo.20203771" target="_blank" rel="noreferrer">CC BY 4.0 software supplement</a>, attributed to Tomáš Peitl and Leroy Chew</td><td>Attribute the source, mark modifications, and provide the corresponding source and notices with binaries. See the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qrp2rup-current-license-source.json" target="_blank" rel="noreferrer">source record</a> and <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qrp2rup-distribution-files.json" target="_blank" rel="noreferrer">materials list</a>.</td></tr><tr><td>drat-trim</td><td>Marijn Heule and Nathan Wetzler; <a href="https://github.com/marijnheule/drat-trim/blob/2e3b2dc0ecf938addbd779d42877b6ed69d9a985/drat-trim.c" target="_blank" rel="noreferrer">pinned source header</a>, MIT</td><td>Retain the copyright, license, and disclaimer from the source header when distributing the binary.</td></tr><tr><td>QBFEVAL data, public and hidden instances, and transformed copies</td><td><a href="https://www.qbflib.org/qbfeval20.php" target="_blank" rel="noreferrer">Official QBFEVAL 2020 rules</a>; <a href="https://doi.org/10.5281/zenodo.18832723" target="_blank" rel="noreferrer">ParaProofa v1 supplement</a>, CC BY 4.0</td><td>Attribute Mark Peyrer, Maximilian Heisinger, Martina Seidl, and the original instance families. The three BMC instances retain University of Toronto 2007 non-commercial teaching and research terms. See the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qbf-data-distribution-source.json" target="_blank" rel="noreferrer">per-instance source record</a> and <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/qbf-data-distribution-files.json" target="_blank" rel="noreferrer">included-material list</a>.</td></tr></tbody></table><p>The exact acknowledgment required by the log4j 1.2.8 terms is: “This product includes software developed by the Apache Software Foundation (<a href="http://www.apache.org/" target="_blank" rel="noreferrer">http://www.apache.org/</a>).” The complete original terms are in <code>third-party/Log4j-1.2.8-Apache-1.1.txt</code>.</p><h2 id="lean-construction-and-system-components" tabindex="-1">Lean, construction, and system components <a class="header-anchor" href="#lean-construction-and-system-components" aria-label="Permalink to &quot;Lean, construction, and system components&quot;">​</a></h2><p>Read each row for the pinned component or mathematical-data source.</p><table tabindex="0"><thead><tr><th>Resource</th><th>Source and terms</th><th>Attribution and distribution conditions</th></tr></thead><tbody><tr><td>Lean 4.33.0-rc1 and elan 4.2.3</td><td><a href="https://github.com/leanprover/lean4/blob/v4.33.0-rc1/LICENSE" target="_blank" rel="noreferrer">Lean license</a> and <a href="https://github.com/leanprover/elan/blob/master/LICENSE" target="_blank" rel="noreferrer">elan license</a>, Apache-2.0</td><td>Retain both notices and applicable notices for components included in the image.</td></tr><tr><td>mathlib commit <code>5b3f719bf129e3cf48daf6ff76a2ec5cb6e9b1e3</code></td><td><a href="https://github.com/leanprover-community/mathlib4/blob/5b3f719bf129e3cf48daf6ff76a2ec5cb6e9b1e3/LICENSE" target="_blank" rel="noreferrer">Pinned mathlib license</a>, Apache-2.0</td><td>Retain file-level copyright headers. Use matching source, compiled cache, version, and notices.</td></tr><tr><td>Batteries, Aesop, Qq, ProofWidgets, ImportGraph, LeanSearchClient, and Plausible</td><td>Licenses at their pinned commits; Apache-2.0 notices are in <code>third-party/</code></td><td>Retain component notices. ProofWidgets&#39; generated browser code has dependencies with their own licenses; see the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/proofwidgets-npm-license-materials.json" target="_blank" rel="noreferrer">frontend license record</a>.</td></tr><tr><td>Lean4 CLI commit <code>da07ca808b6718cb2aed14dba154e5a08b8f8ecf</code></td><td>mhuisi; <a href="https://github.com/leanprover/lean4-cli/blob/da07ca808b6718cb2aed14dba154e5a08b8f8ecf/LICENSE" target="_blank" rel="noreferrer">pinned license</a>, MIT</td><td>Retain its MIT notice; it is separate from Lean&#39;s Apache-2.0 license.</td></tr><tr><td>Frege definition layer based on FormalizedFormalLogic/Foundation</td><td><a href="https://github.com/FormalizedFormalLogic/Foundation/blob/master/LICENSE" target="_blank" rel="noreferrer">Upstream license</a>, Apache-2.0</td><td>Attribute FormalizedFormalLogic/Foundation contributors and retain the license and adaptation notes in the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/frege-reference-source.json" target="_blank" rel="noreferrer">source record</a>.</td></tr><tr><td>Binary-code reference with 136 codewords: <code>tasks/construction/binary-code-a24-10/solution/</code></td><td>Laaksonen and Östergård; derived from parameters and orbit representatives in <a href="https://arxiv.org/abs/1604.06022" target="_blank" rel="noreferrer">their paper</a></td><td>Attribute the authors and identify the source. The task payload consists of the converted codewords. See the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/a24-reference-source.json" target="_blank" rel="noreferrer">reference record</a>.</td></tr><tr><td>Extremal-graph reference: 124 vertices, 629 edges, and Lean encoding</td><td>Jan Goedgebeur, Jorik Jooken, Gwenaël Joret, and Tibo Van den Eede; <a href="https://github.com/AGT-Kulak/searchMaxSizeMinGirth/tree/f6c80b4aa75236b0d4e6ff4f11f197621080f180" target="_blank" rel="noreferrer">fixed upstream source</a>, GPL-3.0</td><td>GPL-3.0 applies to the upstream code and graph data. Retain the original graph, Lean source, attribution, GPL text, and conversion notes. A combined work containing GPL material must meet GPL terms. See the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/extremal-graph-source.json" target="_blank" rel="noreferrer">source record</a> and <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/extremal-graph-distribution-files.json" target="_blank" rel="noreferrer">component file list</a>.</td></tr><tr><td>Locally generated examples, including the Petersen graph, cross polytopes, and root systems</td><td>Task-specific generation code and descriptions</td><td>Keep mathematical-object data distinct from copied code and third-party programs; apply each source&#39;s terms to the actual material.</td></tr></tbody></table><p>Container images include Debian, Ubuntu, GNU tools, Java, Python, and other system components. Each component retains its own license. Retain the component notices and provide corresponding source when required. Exact versions and source locations are in the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/system-license-materials.json" target="_blank" rel="noreferrer">system license materials</a>.</p><p>Graphviz 15.0.0 embedded in ProofWidgets is EPL-2.0; the outer <code>@hpcc-js/wasm</code> package is Apache-2.0. Distribution must include the EPL text and a usable way to obtain Graphviz source and the modifications. Expat 2.8.1, Emscripten 6.0.0, and Penrose Rust components keep their original licenses; see the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/proofwidgets-embedded-components.json" target="_blank" rel="noreferrer">embedded component record</a>.</p><h2 id="additional-full-materials" tabindex="-1">Additional Full materials <a class="header-anchor" href="#additional-full-materials" aria-label="Permalink to &quot;Additional Full materials&quot;">​</a></h2><p>These notices also apply to Full and same-source offline packages:</p><ul><li><strong>JSPLIB data:</strong> ScheduleOpt/benchmarks and applicable adaptations are CC BY-SA 4.0. Attribute the original instance authors and ScheduleOpt contributors; see the <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/full-review.json" target="_blank" rel="noreferrer">source record</a>.</li><li><strong>MCQD maximum-clique code:</strong> <code>mcqd_anytime.h</code> carries Janez Konc&#39;s GPL-3.0-or-later notice. Preserve its header and identify the node-limit, time-limit, output-removal, and optimality-query modifications.</li><li><strong>Circuit definitions:</strong> Copyright 2026 Samuel Schlesinger, Apache-2.0; used in <code>np-vs-acc</code> and <code>nexp-vs-tc0</code>, with changes described in the source header.</li><li><strong>Tensor-rank definition:</strong> Copyright 2026 Jeroen Zuiddam, Apache-2.0; the formalization source credits Christandl, Hoeberechts, Nieuwboer, Vrana, and Zuiddam. See the per-task source record.</li><li><strong>Sorting-network comparators:</strong> Green 1969; identical comparator data from fixed SorterHunter files, Copyright 2017 Bert Dobbelaere, MIT. Retain attribution and the license when distributing the converted Lean tuples.</li><li><strong>PACE 2019 instances:</strong> M. Ayaz Dzulfikar, Johannes K. Fichte, and Markus Hecher; official <a href="https://zenodo.org/records/3368306" target="_blank" rel="noreferrer">Zenodo record 3368306</a>, CC BY 4.0. Retain other original sources and conversion notes.</li><li><strong>MaxSAT Evaluation 2026 supplement:</strong> Dieter Vandesande, Christoph Jabs, Jeremias Berg, Johannes Fichte, George Katsirelos, Ruben Martins, André Schidler, and Dominik Schreiber; <a href="https://zenodo.org/records/21358014" target="_blank" rel="noreferrer">Zenodo record 21358014</a>, CC BY 4.0. Retain instance-family attribution; included solver software keeps its own license.</li><li><strong>PACE 2024 checker:</strong> Copyright 2023 Philipp Kindermann, Fabian Klute, and Soeren Nickel, MIT. Retain the notice from the included wheel.</li></ul><p>The <a href="https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/docs/licenses/third-party/full-review.json" target="_blank" rel="noreferrer">per-task license record</a> identifies additional MIT, BSD-style, CC0, Apache and GPL components. Follow the <a href="/TCSExam/docs/licenses/distribution/">distribution conditions</a> for materials with unconfirmed terms.</p>',16)])])}const b=t(n,[["render",i]]);export{f as __pageData,b as default};
